def _format_t(path, root=T):
    def kwarg_fmt(kw):
        if isinstance(kw, str):
            return kw
        return repr(kw)
    prepr = ['T' if root is T else 'S']
    i = 0
    while i < len(path):
        op, arg = path[i], path[i + 1]
        if op == '.':
            prepr.append('.' + arg)
        elif op == '[':
            prepr.append("[%r]" % (arg,))
        elif op == '(':
            args, kwargs = arg
            prepr.append("(%s)" % ", ".join([repr(a) for a in args] +
                                            ["%s=%r" % (kwarg_fmt(k), v)
                                             for k, v in kwargs.items()]))
        elif op == 'P':
            return _format_path(path)
        i += 2
    return "".join(prepr)


